(()=>{const q=(s,r=document)=>r.querySelector(s);async function submit(e){const f=e.currentTarget,status=q('[data-newsletter-status]',f)||q('[data-newsletter-status]');if(!f.matches('[data-newsletter-form]'))return;e.preventDefault();const btn=q('button[type="submit"]',f),data=new FormData(f);if(btn)btn.disabled=true;if(status){status.textContent='Joining…';status.removeAttribute('hidden')}try{const r=await fetch(f.action,{method:'POST',body:data,headers:{Accept:'application/json'}}),j=await r.json().catch(()=>({}));if(!r.ok||!j.ok)throw Object.assign(new Error(j.message||j.error||'Subscription failed'),{fallback:j.fallback});if(status)status.textContent='Check your inbox. Your free glossary cheat sheet is ready.';const next=j.next||data.get('next');if(next)location.assign(next)}catch(err){if(status)status.textContent='The direct sign-up is unavailable right now. Use the hosted fallback below.';const a=q('[data-newsletter-fallback]',f.closest('[data-newsletter-shell]')||document);if(a&&err.fallback)a.href=err.fallback}finally{if(btn)btn.disabled=false}}function wire(){document.querySelectorAll('[data-newsletter-form]').forEach(f=>{if(f.dataset.wired)return;f.dataset.wired='1';f.addEventListener('submit',submit)})}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',wire,{once:true}):wire()})();
